import{_ as n,l as i,o as e,c as s,v as r,p as l,x as t,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"资产定价基本定理","description":"","frontmatter":{"title":"资产定价基本定理","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ftap.md","filePath":"econ/ftap.md","lastUpdated":1789023840000}'),m={name:"econ/ftap.md"};function h(A,a,E,_,b,f){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="资产定价基本定理" tabindex="-1">资产定价基本定理 <a class="header-anchor" href="#资产定价基本定理" aria-label="Permalink to &quot;资产定价基本定理&quot;">​</a></h1><div class="epigraph"><p>无套利当且仅当存在严格正的状态价格（有限市场）；在更一般的空间里，当且仅当存在等价鞅测度。</p><footer>—— 据 Harrison and Kreps, Martingales and Arbitrage in Multiperiod Securities Markets, JET 1979；Dalang, Morton and Willinger 1990；Delbaen and Schachermayer 1994</footer></div><p><a href="/econ/law-of-one-price">上一课</a>拆开了 LOP 与 NA。本课缺口是把 NA 收成一条定理，并标明有限与无穷的差别。不重做 Stiemke 的线性代数，不估计任何 \\(m\\)。主干 <a href="/econ/stochastic-discount-factor">SDF</a> 已经把结论当会计用；本课补的是「定理」本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限状态、一期：NA ⇔ 存在 \\(q\\gg 0\\) 使 \\(p=A^\\top q\\)。这是 FTAP 的教室版。多期有限树：NA ⇔ 存在等价概率 \\(\\mathbb{Q}\\sim\\mathbb{P}\\)，使折现价格是 \\(\\mathbb{Q}\\)–鞅。连续交易、无界损失：无套利要升级成无免费午餐（NFLVR），FTAP 才恢复「⇔ 存在等价局部鞅测度」（Delbaen–Schachermayer）。缺口是承认：口头「无套利即有定价核」在有限世界是定理，在连续时间是一串越来越强的定义。</p><p>本栏用教室版做主干，连续时间课序再碰到局部鞅。不要把 1994 年的泛函分析写进每一课后文。</p><p><span class="marginnote">第一基本定理：NA（或 NFLVR）⇔ 存在等价鞅测度。第二基本定理：市场完全 ⇔ 该测度唯一。Kreps、Harrison–Pliska 把多期有限与布朗模型写清。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>有限情形：分离超平面把「套利锥」与价格向量分开，法向量即 \\(q\\)。归一化 \\(\\sum q=1\\) 得风险中性概率；除以 \\(\\pi\\) 得 \\(m\\)。多期：每个节点一个局部 \\(q\\)，串成密度过程 \\(Z_t=\\mathrm{d}\\mathbb{Q}/\\mathrm{d}\\mathbb{P}|_{\\mathcal{F}_t}\\)，折现价格 \\(S/B\\) 在 \\(\\mathbb{Q}\\) 下是鞅。完全：每个或有支付可复制，测度唯一，未定权益有唯一无套利价格。不完全：测度一个凸集，未定权益一个价格区间——后课定价界。</p><p>与 <a href="/econ/state-prices">状态价格</a> 的关系：教室版 FTAP 就是「NA 给出 Arrow 价格为正」；状态价格课从完全市场的商品语言入手，本课从套利语言入手，同一 \\(q\\)。</p>',10)),(e(),l(d,null,{default:t(()=>[c(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20NA%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%22%5D%20--%3E%20Q%5B%22%E5%AD%98%E5%9C%A8%20q%20%3E%3E%200%20%E6%88%96%20EMM%22%5D%0A%20%20COMP%5B%22%E5%AE%8C%E5%85%A8%22%5D%20--%3E%20UNIQ%5B%22EMM%20%E5%94%AF%E4%B8%80%22%5D%0A%20%20INCOMP%5B%22%E4%B8%8D%E5%AE%8C%E5%85%A8%22%5D%20--%3E%20SET%5B%22EMM%20%E5%87%B8%E9%9B%86%22%5D%0A%20%20Q%20--%3E%20SDF%5B%22m%20%3D%20%E5%AF%86%E5%BA%A6%20%2F%20%E6%A6%82%E7%8E%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不要把 FTAP 写成「市场有效」。有效是相对信息集无经济利润，必须联合一个 \\(m\\)；FTAP 只说若 NA 则 \\(m\\) 存在。有 \\(m\\) 仍可对某个信息集无效——那是联合假说的另一半。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是对偶。套利是原空间里的方向；正定价核是对偶空间里的严格正泛函。有限维两者干净地互推。无穷维需要闭包：有的「近似套利」序列在极限才变成午餐，NFLVR 把这些序列也禁止掉，对偶才重新出现。经济含义不变：禁止免费午餐，才能给每一种可交易支付标一个线性价格。</p><p>信息课序的 NA 更脆：买卖两点、卖空限制，可行集不是线性空间，对偶变成不等式，价格变成区间。FTAP 的工作假设是摩擦先关掉——上一课接口已经预告。</p><p><span class="marginnote">Harrison–Kreps 1979 还允许「免费处置」等弱套利概念，并为投机给出鞅价格。后课 Harrison–Kreps 鞅定价专写动态与信念。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明 Delbaen–Schachermayer。后文连续时间组合用到布朗与伊藤时，默认教室版的精神：无套利 ⇒ 有等价测度；完全 ⇒ 唯一。也不要把「存在 EMM」说成代表性主体存在——代表性主体是均衡加总，FTAP 只是无套利。Lucas 树会给出一个具体的 \\(m\\)，那是均衡，不是定理的全部解。</p><p>下一课把 EMM 单独钉：何谓等价、何谓鞅、折现用哪一个账户。</p><p>后课默认：有限市场 NA ⇔ 正状态价格 ⇔ 存在 SDF \\(m\\gt 0\\)。完全则唯一。连续时间用 NFLVR 替换 NA。有效市场假说不是 FTAP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>教室版 FTAP：无套利 ⇔ 存在 \\(q\\gg 0\\)（或 \\(m\\gt 0\\)）。</li><li>第二定理：完全 ⇔ 等价鞅测度唯一。</li><li>连续时间把 NA 升级为 NFLVR，精神仍是对偶。</li><li>出处：Harrison and Kreps, <em>JET</em> 1979；Dalang–Morton–Willinger；Delbaen and Schachermayer, 1994。</li></ul>',11))])}const T=n(m,[["render",h]]);export{P as __pageData,T as default};
